import{z as h,x as m,o as t,c as A,q as o,j as E,D as e,d as r,s as p,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"截断重要性采样","description":"","frontmatter":{"title":"截断重要性采样","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/truncated-importance-sampling.md","filePath":"llm/truncated-importance-sampling.md","lastUpdated":1791063341000}'),s={name:"llm/truncated-importance-sampling.md"};function c(B,a,d,_,P,b){const l=m("Mermaid");return t(),A("div",null,[a[2]||(a[2]=o('<h1 id="截断重要性采样" tabindex="-1">截断重要性采样 <a class="header-anchor" href="#截断重要性采样" aria-label="Permalink to &quot;截断重要性采样&quot;">​</a></h1><div class="epigraph"><p>样本来自旧策略，梯度却对当前策略：比率必须截断，否则长链上的权重爆炸，clip 只是其中一种截法。</p><footer>—— Precup 等的重要性采样；Espeholt 等 IMPALA 的 V-trace；PPO clip 与 MiniMax-M1 的 clip-IS</footer></div><p><a href="/llm/kl-free-rl">上一课</a>去掉冻结参考的 KL 之后，约束更依赖「这批 rollout 相对 \\(\\pi_{\\mathrm{old}}\\) 别用过头」。缺口是：<strong>PPO epoch &gt; 1 或异步生成一出现，数据就已经是 off-policy，重要性比率要截断。</strong> 本课写截断 IS，不把 PPO clip 再推导一遍——clip 是截断在代理目标上的实现。<a href="/llm/gspo">GSPO</a> 把比率改到序列级，是粒度之争，本课先钉 token 级截断。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>on-policy 时 \\(r_t=\\pi_\\theta/\\pi_{\\mathrm{old}}=1\\)。更新若干 minibatch 后 \\(\\pi_\\theta\\) 已变，未截断的 \\(\\pi_\\theta/\\pi_{\\mathrm{old}}\\) 在长序列上连乘或逐步乘，方差指数升。PPO 用 \\(\\mathrm{clip}(r_t,1-\\varepsilon,1+\\varepsilon)\\) 限制代理。截断重要性采样（truncated IS）更古典：\\(\\bar\\rho=\\min(\\bar c, \\pi_\\theta/\\pi_{\\mathrm{beh}})\\)，用 \\(\\bar\\rho\\) 校正期望。V-trace 再对 \\(\\bar\\rho\\) 与 \\(\\bar c\\) 分两层截断，修正价值。LLM 栈里常混用这些词：有人把 PPO clip 叫做 IS，有人另对 logprob 比做 min。</p><p><span class="marginnote">术语翻译：重要性采样就是「拿旧策略生成的数据来评新策略」时，给每个样本发一张补偿价签——这个动作在新策略下更常见，权重调高；更罕见，权重调低。比率 \\(\\pi_\\theta/\\pi_{\\mathrm{beh}}\\) 就是那张价签。</span></p><p><span class="marginnote">数字实例：某 token 在新策略下的概率是旧策略的 1.05 倍，看着无害；一条 64 token 的轨迹连乘 \\(1.05^{64}\\approx 23\\)，权重差 23 倍，梯度方向就被这一条轨迹劫持了。截断干的事，就是把每个乘数先压回上限。</span></p><p>MiniMax-M1 认为多轮 off-policy 下 Clip-Higher 仍丢分叉词，改为对 IS 权重 clip。要点是：<strong>截的是校正权重，还是近端代理，必须说清。</strong> epoch 越多，未截断比率的尾巴越肥，这与「多刷同一批省生成」直接冲突。</p><h3 id="行为策略是谁" tabindex="-1">行为策略是谁 <a class="header-anchor" href="#行为策略是谁" aria-label="Permalink to &quot;行为策略是谁&quot;">​</a></h3><p>同步 PPO：\\(\\pi_{\\mathrm{beh}}=\\pi_{\\mathrm{old}}\\)，生成时缓存。异步：\\(\\pi_{\\mathrm{beh}}\\) 是若干版本前的生成引擎，必须带版本号重算或存储 logprob。用错分母，截断再狠也是错校正。下一课 off-policy 校正把系统与公式接起来。</p><p><span class="marginnote">参考 \\(\\pi_{\\mathrm{ref}}\\) 不是行为策略。KL 用 ref；IS 用 beh。三份对数概率不要混槽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐步：\\(\\rho_t=\\pi_\\theta(a_t\\mid s_t)/\\pi_{\\mathrm{beh}}(a_t\\mid s_t)\\)，\\(\\rho_t\\leftarrow\\min(\\rho_t,c)\\)。序列：\\(\\rho=\\min(c,\\pi_\\theta(y\\mid x)/\\pi_{\\mathrm{beh}}(y\\mid x))\\)，或长度归一的几何平均（GSPO 方向）。价值用 V-trace 时，另选 \\(\\bar c\\)。实践：先保证生成时存 \\(\\log\\pi_{\\mathrm{beh}}\\)，训练时用当前 \\(\\pi_\\theta\\) 重前向，禁止用生成时的 \\(\\log\\pi_\\theta\\) 冒充当前。半精度下在 fp32 里算差。</p>',13)),(t(),E(n,null,{default:e(()=>[p(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEH%5B%22%CF%80_beh%20%E7%94%9F%E6%88%90%E5%B9%B6%E7%BC%93%E5%AD%98%20log%CF%80%22%5D%20--%3E%20RHO%5B%22%CF%81%20%3D%20%CF%80_%CE%B8%20%2F%20%CF%80_beh%22%5D%0A%20%20TH%5B%22%E5%BD%93%E5%89%8D%20%CF%80_%CE%B8%20%E9%87%8D%E5%89%8D%E5%90%91%22%5D%20--%3E%20RHO%0A%20%20RHO%20--%3E%20TR%5B%22min(%CF%81%2C%20c)%20%E6%88%AA%E6%96%AD%22%5D%0A%20%20TR%20--%3E%20ADV%5B%22%E5%8A%A0%E6%9D%83%E4%BC%98%E5%8A%BF%20%2F%20%E4%BB%A3%E7%90%86%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("p",null,"\\(c\\) 与 PPO \\(\\varepsilon\\) 不要叠成未声明的双重截断：若目标已是 clip 代理，不必再乘一层 \\(\\min(\\rho,c)\\)，除非论文明确是 clip-IS 变体。",-1)),a[4]||(a[4]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(t(),E(n,null,{default:e(()=>[p(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%7B%22%E6%88%AA%E6%96%AD%E9%98%88%E5%80%BC%20c%20%E6%80%8E%E4%B9%88%E9%80%89%22%7D%20--%3E%20S%5B%22c%20%E5%A4%AA%E5%B0%8F%22%5D%0A%20%20C%20--%3E%20L%5B%22c%20%E5%A4%AA%E5%A4%A7%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E9%AB%98%E6%AF%94%E7%8E%87%E5%8C%BA%E5%9F%9F%E8%A2%AB%E7%A0%8D%E6%8E%89%EF%BC%9A%E6%9C%89%E6%95%88%E6%9B%B4%E6%96%B0%E5%8F%98%E7%A8%80%22%5D%0A%20%20S%20--%3E%20S2%5B%22%E8%AE%AD%E7%BB%83%E7%A8%B3%E4%BD%86%E5%AD%A6%E5%BE%97%E6%85%A2%EF%BC%8C%E5%81%8F%E5%B7%AE%E6%9B%B4%E5%A4%A7%22%5D%0A%20%20L%20--%3E%20L1%5B%22%E6%96%B9%E5%B7%AE%E5%9B%9E%E6%9D%A5%EF%BC%9A%E9%95%BF%E9%93%BE%E4%B9%98%E7%A7%AF%E9%87%8D%E6%96%B0%E7%88%86%E7%82%B8%22%5D%0A%20%20L%20--%3E%20L2%5B%22%E6%A2%AF%E5%BA%A6%E5%99%AA%E5%A3%B0%E5%A4%A7%EF%BC%8C%E6%9B%B4%E6%96%B0%E6%96%B9%E5%90%91%E5%8F%91%E6%8A%96%22%5D%0A%20%20M%5B%22%E9%80%82%E4%B8%AD%EF%BC%9A%E7%94%A8%E5%81%8F%E5%B7%AE%E6%8D%A2%E6%96%B9%E5%B7%AE%EF%BC%8C%E6%B2%A1%E6%9C%89%E5%85%8D%E8%B4%B9%E5%8D%88%E9%A4%90%22%5D%20--%3E%20C%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>未截断 IS 无偏、高方差；截断有偏、低方差。偏差表现为：被截掉的高比率区域不再更新，正是「走得太远的 token」。这与 PPO clip 精神相同。\\(c\\) 太小，有效更新稀；太大，方差回来。长链上 token 级 \\(\\rho_t\\) 即使逐步截断，累积仍可偏，这是 GSPO 改序列粒度的动机。本课承认：截断是偏置换方差，不是免费午餐。</p><p><span class="marginnote">\\(\\rho=0\\) 的动作（当前策略已赋零概率）梯度消失。词表约束或禁止采样列表变化时，要重对齐。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>真 on-policy（每步重新生成、单 epoch）截断几乎不触发，本课边际小。异步与大 epoch 才是主场。无 KL 时没有 ref 把策略拉回，截断几乎是唯一近端闸。三份对数概率分槽：\\(\\theta\\)、behavior、reference；截断阈值与 PPO \\(\\epsilon\\) 若同时存在，必须声明有没有双重截。下一课把校正放到「多版本混合 batch」的系统现实里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一旦离开严格 on-policy，就要对 \\(\\pi_\\theta/\\pi_{\\mathrm{beh}}\\) 截断，控制 IS 方差。</li><li>clip 代理与截断权重是两种实现，不要双重截而不声明。</li><li>分母是行为策略，不是 \\(\\pi_{\\mathrm{ref}}\\)；必须缓存或按版本重算 logprob。</li><li>截断有偏；长链粒度问题指向 GSPO。</li><li>出处：Precup 等 IS；Espeholt 等 V-trace / IMPALA；Schulman PPO；MiniMax-M1 clip-IS。</li></ul>',6))])}const C=h(s,[["render",c]]);export{D as __pageData,C as default};
